
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_2d_pbe_HO2D_2_zk():
    # Prepare the input
    inp = test_data["HO2D"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_2d_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.490131584044175e-01, -8.491283796376763e-01, -8.493133941440326e-01, -8.496084728026503e-01, -8.500740790635583e-01, -8.507965623861330e-01, -8.518889368805767e-01, -8.534749208109622e-01, -8.556255841607768e-01, -8.581523743586518e-01, -8.599365691087493e-01, -8.569740399632326e-01, -8.382229117091896e-01, -7.821555466427133e-01, -6.681741509929128e-01, -4.859560453429277e-01, -2.225406749820471e-01, -4.655359880746609e-02, -3.091538460681012e-03, -3.244534272247366e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


